<script setup lang="ts">
import { Head, Link, router, useForm } from '@inertiajs/vue3'
import AuthenticatedLayout from '../../../Layouts/AuthenticatedLayout.vue'
type ReleaseNote={id:number;version:string;title:string;summary:string|null;markdown_body:string;status:string;released_on:string|null}
const props=defineProps<{releaseNote:ReleaseNote|null}>()
const defaultMarkdown=`# 版本说明\n\n## 新增\n\n- 内容\n\n## 修复\n\n- 内容`
const form=useForm({version:props.releaseNote?.version??'',title:props.releaseNote?.title??'',summary:props.releaseNote?.summary??'',markdown_body:props.releaseNote?.markdown_body??defaultMarkdown,released_on:props.releaseNote?.released_on??new Date().toISOString().slice(0,10)})
const submit=()=>props.releaseNote?form.patch(`/settings/changelog/${props.releaseNote.id}`):form.post('/settings/changelog')
const setPublished=(published:boolean)=>props.releaseNote&&router.post(`/settings/changelog/${props.releaseNote.id}/${published?'publish':'unpublish'}`)
</script>
<template><Head :title="`${releaseNote?'编辑版本记录':'新建版本记录'} · BYL ERP`"/><AuthenticatedLayout :title="releaseNote?'编辑版本记录':'新建版本记录'" :breadcrumbs="[{label:'BYL ERP',href:'/dashboard'},{label:'指南',href:'/guides'},{label:'版本更新',href:'/settings/changelog'},releaseNote?'编辑':'新建']"><form class="erp-form-page" @submit.prevent="submit"><div class="erp-form-content"><div class="erp-form-header-row"><div><p class="mvp-kicker">PUBLISHABLE RELEASE NOTE</p><h2 class="erp-form-title">{{releaseNote?.title||'新建版本记录'}}</h2></div><div class="mvp-actions"><Link class="erp-btn erp-btn-secondary" href="/settings/changelog">返回</Link><button class="erp-btn erp-btn-primary" type="submit">保存</button></div></div><div class="erp-form-card"><div class="erp-form-grid"><label class="erp-form-field"><span class="erp-form-label">版本号</span><input v-model="form.version" class="erp-input" placeholder="v1.5.2"></label><label class="erp-form-field"><span class="erp-form-label">发布日期</span><input v-model="form.released_on" type="date" class="erp-input"></label><label class="erp-form-field ord-span-2"><span class="erp-form-label">标题</span><input v-model="form.title" class="erp-input"></label><label class="erp-form-field ord-span-2"><span class="erp-form-label">摘要</span><textarea v-model="form.summary" class="erp-input" rows="3"></textarea></label></div></div><div class="erp-form-card"><h3 class="erp-form-card-title">Markdown 发布说明</h3><textarea v-model="form.markdown_body" class="erp-input release-editor" rows="24"></textarea></div><div v-if="releaseNote" class="erp-form-card"><h3 class="erp-form-card-title">发布状态</h3><p>当前：{{releaseNote.status==='published'?'已发布':'草稿'}}</p><div class="mvp-actions"><button v-if="releaseNote.status!=='published'" type="button" class="erp-btn erp-btn-primary" @click="setPublished(true)">发布版本记录</button><button v-else type="button" class="erp-btn erp-btn-secondary" @click="setPublished(false)">转为草稿</button><Link class="erp-btn erp-btn-secondary" :href="`/settings/changelog/${releaseNote.id}`">预览 / 阅读</Link></div></div></div></form></AuthenticatedLayout></template>
<style scoped>.release-editor{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;line-height:1.6;min-height:520px}.ord-span-2{grid-column:span 2}@media(max-width:800px){.ord-span-2{grid-column:auto}}</style>
